// Replay all generated bytes through exported Wasm entry points, observing the
// complete head after every submission, including every refusal.
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import path from 'node:path';
import {gunzipSync} from 'node:zlib';

const groups = ['matrix','length','signed','gate'];
const dir = process.argv[2] || 'logs/r9/vectors';
const mod = new WebAssembly.Module(readFileSync('core/Core9.wasm'));
assert.deepEqual(WebAssembly.Module.imports(mod), []);
function load(file) {
  const name = path.join(dir,file);
  try { return readFileSync(name); }
  catch(e) { if (e.code !== 'ENOENT') throw e; return gunzipSync(readFileSync(name+'.gz')); }
}
let total = 0, agree = 0, accepts = 0, successfulSigned = [], mismatches = [];
for (const group of groups) {
  const api = new WebAssembly.Instance(mod).exports;
  const keys = readFileSync(group === 'gate' ? 'logs/r9/gate-vectors/keys.bin' : 'logs/r9/vector-signatures/keys.bin');
  let offset = 0, accepted = 0, agreed = 0;
  function input(bytes) {
    let overflow = false;
    for (const b of bytes) if (api.input(b) !== 1) overflow = true;
    return overflow;
  }
  assert.equal(input(keys), false);
  assert.equal(api.init(), 1);
  if (group === 'gate') {
    const staged = readFileSync('core/FixedGenesis9.wasm');
    for (let j = 0; j < staged.length; j+=8192) {
      assert.equal(input(staged.subarray(j,j+8192)), false);
      assert.equal(api.feed(), 1);
    }
  }
  const wires = load(group+'.bin');
  const rows = load(group+'.tsv').toString().trimEnd().split('\n');
  for (const [idx,row] of rows.entries()) {
    const [label,len,verdict,expectedHead] = row.split('\t');
    const bytes = wires.subarray(offset,offset+Number(len));
    assert.equal(bytes.length, Number(len));
    const overflow = input(bytes);
    const actual = api.step();
    const head = Buffer.from(Array.from({length:32},(_,i) => api.head(i))).toString('hex');
    assert.equal(api.head(32),256);
    if (actual === Number(verdict) && head === expectedHead) agreed++;
    else mismatches.push({group,index:idx,label,offset,length:bytes.length,wireHex:bytes.toString('hex'),
        expectedVerdict:Number(verdict),expectedHead,wasmVerdict:actual,wasmHead:head,overflow});
    if (actual === 1) { accepted++; if (group === 'signed') successfulSigned.push(label); }
    if (group === 'gate') console.log('gate',label,'model',verdict,expectedHead,'wasm',actual,head);
    total++;
    offset += bytes.length;
  }
  assert.equal(offset,wires.length);
  agree += agreed; accepts += accepted;
  console.log(group,agreed,'of',rows.length,'agree;',accepted,'accepted,',rows.length-accepted,'refused');
}
console.log('Signed trace accepted',successfulSigned.join(', '));
for (const mismatch of mismatches) console.log('DISAGREEMENT', JSON.stringify(mismatch));
console.log('DIFFERENTIAL:',agree,'of',total,'agree;',accepts,'accepted;',total-accepts,'refused');
assert.equal(mismatches.length,0);
assert.ok(total >= 500);
